import { createClient } from "@/lib/supabase/server";
import { PageHeader } from "@/components/PageHeader";
import { formatCurrency, formatDate } from "@/lib/utils";
import Link from "next/link";
import { SubNav } from "./SubNav";
import { DeleteButton } from "./DeleteButton";
import { MergeButton } from "./MergeButton";
import CustomerImportExport from "./CustomerImportExport";

export default async function CustomersPage(props: { searchParams?: Promise<Record<string, string | undefined>> | Record<string, string | undefined> }) {
  const searchParams = (await Promise.resolve(props.searchParams || {})) as Record<string, string | undefined>;
  const supabase = await createClient();

  let phoneCustomerIds: string[] | null = null;
  if (searchParams.phone) {
    const [mainRes, phoneRes, contactRes] = await Promise.all([
      supabase.from("customers").select("id").ilike("phone", `%${searchParams.phone}%`),
      supabase.from("customer_phones").select("customer_id").ilike("phone", `%${searchParams.phone}%`),
      supabase.from("customer_contacts").select("customer_id").ilike("phone", `%${searchParams.phone}%`),
    ]);
    const mainIds = mainRes.data?.map((c: { id: string }) => c.id) || [];
    const extraIds = phoneRes.data?.map((p: { customer_id: string }) => p.customer_id) || [];
    const contactIds = contactRes.data?.map((c: { customer_id: string }) => c.customer_id) || [];
    phoneCustomerIds = [...new Set([...mainIds, ...extraIds, ...contactIds])];
  }

  const pageSize = 20;
  const page = Math.max(1, parseInt(searchParams.page || "1", 10));
  const from = (page - 1) * pageSize;
  const to = from + pageSize - 1;

  let query = supabase
    .from("customers")
    .select("id, name, phone, gender, company, address, star_level, id_card, notes, total_spent, created_at, vehicles(id, plate_number)", { count: "exact" })
    .order("created_at", { ascending: false });

  if (searchParams.name) query = query.ilike("name", `%${searchParams.name}%`);
  if (searchParams.phone) {
    if (phoneCustomerIds && phoneCustomerIds.length > 0) {
      query = query.in("id", phoneCustomerIds);
    } else {
      query = query.eq("id", "no-match");
    }
  }
  if (searchParams.company) query = query.ilike("company", `%${searchParams.company}%`);
  if (searchParams.address) query = query.ilike("address", `%${searchParams.address}%`);

  query = query.range(from, to);

  const { data: customers, count } = await query;
  const total = count || 0;
  const totalPages = Math.max(1, Math.ceil(total / pageSize));

  const customerIds = customers?.map((c: { id: string }) => c.id) || [];

  const { data: memberMap } = customerIds.length > 0
    ? await supabase.from("members").select("customer_id, card_no, balance, id").in("customer_id", customerIds)
    : { data: [] };

  const { data: allContacts } = customerIds.length > 0
    ? await supabase
        .from("customer_contacts")
        .select("id, customer_id, name, phone, relationship")
        .in("customer_id", customerIds)
        .order("created_at", { ascending: true })
    : { data: [] };

  interface MemberInfo {
    id: string;
    customer_id: string;
    card_no: string;
    balance: number | null;
  }

  interface ContactInfo {
    id: string;
    customer_id: string;
    name: string;
    phone: string | null;
    relationship: string | null;
  }

  interface VehicleInfo {
    id: string;
    plate_number: string;
  }

  interface CustomerRow {
    id: string;
    name: string;
    phone: string | null;
    gender: string | null;
    company: string | null;
    address: string | null;
    star_level: number | null;
    id_card: string | null;
    notes: string | null;
    total_spent: number | null;
    created_at: string;
    vehicles: VehicleInfo[] | null;
  }

  const membersByCustomer: Record<string, MemberInfo> = {};
  memberMap?.forEach((m: MemberInfo) => {
    membersByCustomer[m.customer_id] = m;
  });

  const contactsByCustomer: Record<string, ContactInfo[]> = {};
  allContacts?.forEach((c: ContactInfo) => {
    if (!contactsByCustomer[c.customer_id]) contactsByCustomer[c.customer_id] = [];
    contactsByCustomer[c.customer_id].push(c);
  });

  return (
    <div>
      <PageHeader
        title="客户管理"
        description={`共 ${total} 位客户`}
        action={{ href: "/customers/new", label: "新增客户" }}
      />

      <SubNav />

      {/* 搜索栏 */}
      <form method="GET" className="mb-4 bg-white rounded-xl border border-gray-200 p-4">
        <div className="grid grid-cols-1 sm:grid-cols-4 gap-3">
          <input
            name="name"
            type="text"
            defaultValue={searchParams.name}
            placeholder="客户姓名"
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
          />
          <input
            name="phone"
            type="text"
            defaultValue={searchParams.phone}
            placeholder="联系电话"
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
          />
          <input
            name="company"
            type="text"
            defaultValue={searchParams.company}
            placeholder="所属单位"
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
          />
          <input
            name="address"
            type="text"
            defaultValue={searchParams.address}
            placeholder="地址"
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
          />
        </div>
        <div className="mt-3 flex gap-2 justify-end">
          <Link
            href="/customers"
            className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50"
          >
            重置
          </Link>
          <button
            type="submit"
            className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg hover:bg-blue-700"
          >
            搜索
          </button>
        </div>
      </form>

      <div className="mb-4 flex justify-end gap-2">
        <MergeButton />
        <CustomerImportExport customers={customers || []} />
      </div>

      <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm min-w-[1400px]">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left font-medium text-gray-500 w-16 whitespace-nowrap">序号</th>
                <th className="px-6 py-3 text-left font-medium text-gray-500 whitespace-nowrap">客户姓名</th>
                <th className="px-6 py-3 text-left font-medium text-gray-500 whitespace-nowrap">电话</th>
                <th className="px-6 py-3 text-left font-medium text-gray-500 whitespace-nowrap">联系人</th>
                <th className="px-6 py-3 text-left font-medium text-gray-500 whitespace-nowrap">所属单位</th>
                <th className="px-6 py-3 text-left font-medium text-gray-500 whitespace-nowrap">地址</th>
                <th className="px-6 py-3 text-left font-medium text-gray-500 whitespace-nowrap">星级</th>
                <th className="px-6 py-3 text-left font-medium text-gray-500 whitespace-nowrap">累计消费</th>
                <th className="px-6 py-3 text-left font-medium text-gray-500 whitespace-nowrap">关联车辆</th>
                <th className="px-6 py-3 text-left font-medium text-gray-500 whitespace-nowrap">会员</th>
                <th className="px-6 py-3 text-left font-medium text-gray-500 whitespace-nowrap">注册时间</th>
                <th className="px-6 py-3 text-left font-medium text-gray-500 whitespace-nowrap">操作</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {customers?.map((customer: CustomerRow, idx: number) => (
                <tr key={customer.id} className="hover:bg-gray-50">
                  <td className="px-4 py-4 text-gray-500 text-sm">{(page - 1) * pageSize + idx + 1}</td>
                  <td className="px-6 py-4 font-medium text-gray-900">
                    {customer.name}
                    {customer.gender && <span className="ml-1 text-xs text-gray-400">{customer.gender}</span>}
                  </td>
                  <td className="px-6 py-4 text-gray-600">{customer.phone}</td>
                  <td className="px-6 py-4 text-gray-600">
                    {(contactsByCustomer[customer.id] || []).length > 0 ? (
                      <div className="space-y-1">
                        {contactsByCustomer[customer.id].map((c: ContactInfo) => (
                          <div key={c.id} className="text-xs">
                            <span className="font-medium">{c.name}</span>
                            <span className="text-gray-400 mx-1">·</span>
                            {c.phone}
                            {c.relationship && <span className="text-gray-400 ml-1">({c.relationship})</span>}
                          </div>
                        ))}
                      </div>
                    ) : (
                      "-"
                    )}
                  </td>
                  <td className="px-6 py-4 text-gray-600">{customer.company || "-"}</td>
                  <td className="px-6 py-4 text-gray-600">{customer.address || "-"}</td>
                  <td className="px-6 py-4 text-gray-600">{"★".repeat(customer.star_level || 1)}{"☆".repeat(5 - (customer.star_level || 1))}</td>
                  <td className="px-6 py-4 text-gray-600">{formatCurrency(customer.total_spent)}</td>
                  <td className="px-6 py-4 text-gray-600">
                    {customer.vehicles?.length > 0 ? (
                      <div className="text-sm">
                        {customer.vehicles.map((v: VehicleInfo, i: number) => (
                          <span key={v.id}>
                            <Link
                              href={`/vehicles/${v.id}/edit`}
                              className="text-blue-600 hover:text-blue-800 hover:underline"
                            >
                              {v.plate_number}
                            </Link>
                            {i < customer.vehicles.length - 1 && <span className="text-gray-400">, </span>}
                          </span>
                        ))}
                      </div>
                    ) : (
                      "-"
                    )}
                  </td>
                  <td className="px-6 py-4">
                    {membersByCustomer[customer.id] ? (
                      <Link
                        href={`/members/${membersByCustomer[customer.id].id}`}
                        className="text-sm text-green-600 hover:text-green-700"
                      >
                        {membersByCustomer[customer.id].card_no}
                        <span className="text-gray-400 ml-1">({formatCurrency(membersByCustomer[customer.id].balance)})</span>
                      </Link>
                    ) : (
                      <Link
                        href={`/members/new?customer_id=${customer.id}`}
                        className="text-sm text-blue-600 hover:text-blue-700"
                      >
                        + 办理会员
                      </Link>
                    )}
                  </td>
                  <td className="px-6 py-4 text-gray-500">{formatDate(customer.created_at)}</td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-3">
                      <Link href={`/customers/${customer.id}`} className="text-xs text-gray-600 hover:text-gray-800 hover:underline">查看</Link>
                      <Link href={`/customers/${customer.id}/edit`} className="text-xs text-blue-600 hover:text-blue-800 hover:underline">编辑</Link>
                      <DeleteButton id={customer.id} />
                    </div>
                  </td>
                </tr>
              ))}
              {(!customers || customers.length === 0) && (
                <tr>
                  <td colSpan={12} className="px-6 py-12 text-center text-gray-400">
                    暂无客户数据
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* 分页 */}
      {totalPages > 1 && (
        <div className="mt-4 flex flex-wrap items-center justify-between gap-3">
          <div className="text-sm text-gray-500">
            共 {total} 条，第 {page}/{totalPages} 页
          </div>
          <div className="flex items-center gap-2">
            <Link
              href={(() => {
                const params = new URLSearchParams();
                if (searchParams.name) params.set("name", searchParams.name);
                if (searchParams.phone) params.set("phone", searchParams.phone);
                if (searchParams.company) params.set("company", searchParams.company);
                if (searchParams.address) params.set("address", searchParams.address);
                params.set("page", String(Math.max(1, page - 1)));
                return `/customers?${params.toString()}`;
              })()}
              className={`px-3 py-1.5 text-sm border border-gray-300 rounded-lg hover:bg-gray-50 ${page <= 1 ? "pointer-events-none opacity-50" : ""}`}
            >
              上一页
            </Link>
            <span className="text-sm text-gray-600 px-2">
              {page} / {totalPages}
            </span>
            <Link
              href={(() => {
                const params = new URLSearchParams();
                if (searchParams.name) params.set("name", searchParams.name);
                if (searchParams.phone) params.set("phone", searchParams.phone);
                if (searchParams.company) params.set("company", searchParams.company);
                if (searchParams.address) params.set("address", searchParams.address);
                params.set("page", String(Math.min(totalPages, page + 1)));
                return `/customers?${params.toString()}`;
              })()}
              className={`px-3 py-1.5 text-sm border border-gray-300 rounded-lg hover:bg-gray-50 ${page >= totalPages ? "pointer-events-none opacity-50" : ""}`}
            >
              下一页
            </Link>
            <form method="GET" className="flex items-center gap-2 ml-4">
              {searchParams.name && <input type="hidden" name="name" value={searchParams.name} />}
              {searchParams.phone && <input type="hidden" name="phone" value={searchParams.phone} />}
              {searchParams.company && <input type="hidden" name="company" value={searchParams.company} />}
              {searchParams.address && <input type="hidden" name="address" value={searchParams.address} />}
              <span className="text-sm text-gray-500">跳转到</span>
              <input
                name="page"
                type="number"
                min={1}
                max={totalPages}
                defaultValue={page}
                className="w-16 px-2 py-1 text-sm border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-center"
              />
              <button
                type="submit"
                className="px-3 py-1.5 text-sm text-white bg-blue-600 rounded-lg hover:bg-blue-700"
              >
                确定
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
